					end
					local n = 0
					for index20, value15 in ipairs(j["history"]) do
						n = n + value15
					end
					local o = n / #j["history"]
					local smoothedSpeed2 = j["smoothedSpeed"] or 0
					local smoothedSpeed3 = smoothedSpeed2 + (o - smoothedSpeed2) * 0.25
					if math["abs"](smoothedSpeed3) < 0.05 then
						smoothedSpeed3 = 0
					end
					local etaSeconds = nil
					local etaFormatted = ""
					if smoothedSpeed3 > 0.1 then
						local c = 100 - lastProgress
