						end
					else
						j["smoothedETA"] = nil
					end
					j["smoothedSpeed"] = smoothedSpeed3
					j["etaSeconds"] = etaSeconds
					j["etaFormatted"] = etaFormatted
					j["lastProgress"] = lastProgress
					j["lastTime"] = lastTime
					if alertThresholdEnabled then
						if lastProgress >= alertThreshold then
							if not j["alertTriggered"] then
								j["alertTriggered"] = true
								local etaFormatted2 = (j["etaFormatted"] and j["etaFormatted"] ~= "")
