			local f = 28
			for index53, value39 in ipairs(c) do
				local targetHighlightVisible = (index53 <= f)
				value39["data"]["TargetHighlightVisible"] = targetHighlightVisible
				if (settings["ESPFadeDuration"] or 0.2) <= 0.01 then
					if value39["data"]["Highlight"]:IsA("Highlight") then
						if value39["data"]["Highlight"]["Enabled"] ~= targetHighlightVisible then
							value39["data"]["Highlight"]["Enabled"] = targetHighlightVisible
						end
					elseif value39["data"]["Highlight"]:IsA("BoxHandleAdornment") then
						if value39["data"]["Highlight"]["Visible"] ~= targetHighlightVisible then
							value39["data"]["Highlight"]["Visible"] = targetHighlightVisible
						end
					end
					if value39["data"]["PuddleHighlight"] and value39["data"]["PuddleHighlight"]:IsA("Highlight") then
						if value39["data"]["PuddleHighlight"]["Enabled"] ~= targetHighlightVisible then
