		end
		function updateESPFadeTransitions(c)
			local performanceMode4 = settings["PerformanceMode"]
			local eSPFadeDuration = performanceMode4 and 0 or (settings["ESPFadeDuration"] or 0.2)
			local g = performanceMode4 or (eSPFadeDuration <= 0.01)
			local eSPFillTransparency = settings["ESPFillTransparency"] or 0.6
			local eSPOutlineTransparency = settings["ESPOutlineTransparency"] or 0.1
			local function j(d, j)
				if not d or not d["Highlight"] then
					return
				end
				local currentAlpha = 0
				if d["TargetHighlightVisible"] ~= false and d["LastAuraEnabled"] then
					currentAlpha = d["DistanceOpacityFactor"] or 1
				end
				if d["CurrentAlpha"] == nil then
					d["CurrentAlpha"] = currentAlpha
				elseif g then
					d["CurrentAlpha"] = currentAlpha
				else
					local g = c / eSPFadeDuration
					if d["CurrentAlpha"] < currentAlpha then
						d["CurrentAlpha"] = math["min"](currentAlpha, d["CurrentAlpha"] + g)
					elseif d["CurrentAlpha"] > currentAlpha then
						d["CurrentAlpha"] = math["max"](currentAlpha, d["CurrentAlpha"] - g)
					end
				end
				local currentAlpha2 = d["CurrentAlpha"]
				local visible3 = currentAlpha2 > 0.005
				if j then
					if d["Highlight"]:IsA("BoxHandleAdornment") then
						if d["Highlight"]["Visible"] ~= visible3 then
							d["Highlight"]["Visible"] = visible3
						end
						if visible3 then
							d["Highlight"]["Transparency"] = 1 - ((1 - eSPFillTransparency) * currentAlpha2)
						end
					end
				else
					if d["Highlight"]:IsA("Highlight") then
						if d["Highlight"]["Enabled"] ~= visible3 then
							d["Highlight"]["Enabled"] = visible3
						end
						if visible3 then
							d["Highlight"]["FillTransparency"] = 1 - ((1 - eSPFillTransparency) * currentAlpha2)
							d["Highlight"]["OutlineTransparency"] = 1 - ((1 - eSPOutlineTransparency) * currentAlpha2)
						end
					end
					if d["PuddleHighlight"] and d["PuddleHighlight"]:IsA("Highlight") then
						if d["PuddleHighlight"]["Enabled"] ~= visible3 then
							d["PuddleHighlight"]["Enabled"] = visible3
						end
						if visible3 then
							d["PuddleHighlight"]["FillTransparency"] = 1 - ((1 - eSPFillTransparency) * currentAlpha2)
							d["PuddleHighlight"]["OutlineTransparency"] = 1
								- ((1 - eSPOutlineTransparency) * currentAlpha2)
						end
					end
				end
			end
			for key23, value40 in pairs(ActiveESP["Players"]) do
				j(value40, false)
			end
			for key24, value41 in pairs({
				ActiveESP["Generators"],
				ActiveESP["Hooks"],
				ActiveESP["Pallets"],
				ActiveESP["BloodEffects"],
				ActiveESP["Gates"],
				ActiveESP["SCPs"],
			}) do
				for key25, value42 in pairs(value41) do
					j(value42, false)
				end
			end
			for key26, value43 in pairs(ActiveESP["Vaults"]) do
				j(value43, true)
			end
		end
